namespace McpHttpServer.Tools;

[McpServerToolType]
public static class EchoTool
{
    [McpServerTool(Name = "echo"), Description("Echoes back the provided message.")]
    public static string Echo([Description("The message to echo back")] string message)
        => $"Echo: {message}";
}

using ModelContextProtocol.Server;
using System.Text.Json;

namespace McpHttpServer.Resources;

[McpServerResourceType]
public static class ConfigResource
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "app_settings",
        Title = "Application Settings", MimeType = "application/json")]
    public static string GetAppSettings()
    {
        var config = new
        {
            Environment = "Production",
            MaxConnections = 100,
            Features = new { DarkMode = true, BetaAccess = false }
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

